"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowUp, Check, Mic, X } from "lucide-react";
import { useVoiceInput, VOICE_MAX_SECONDS } from "@/lib/ai/use-voice-input";

const clock = (ms: number) => { const seconds = Math.floor(ms / 1000); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`; };

/**
 * The mic for a text input. A tap or a hold both start recording (on release, which Safari needs for the mic);
 * live words show over the input with a level meter, then Send sends them, Done puts them in the input to edit,
 * and Cancel or Escape discards them. Put it inside a `relative` form: the recording view covers that form.
 */
export function VoiceInput({ onSend, onDone, autoStart = false, disabled = false, compact = false }: {
  onSend: (text: string) => void; onDone: (text: string) => void; autoStart?: boolean; disabled?: boolean; compact?: boolean;
}) {
  const voice = useVoiceInput((action, text) => action === "send" ? onSend(text) : onDone(text));
  const { status, start } = voice;
  const mic = useRef<HTMLButtonElement>(null);
  const done = useRef<HTMLButtonElement>(null);
  const words = useRef<HTMLParagraphElement>(null);
  const wasActive = useRef(false);
  const [now, setNow] = useState(0);
  useEffect(() => { if (autoStart) void start(); }, [autoStart, start]);
  useEffect(() => {
    if (status === "recording") done.current?.focus();
    // Send and Cancel leave nothing focused; Done hands focus to the input itself.
    if (status === "idle" && wasActive.current && (!document.activeElement || document.activeElement === document.body)) mic.current?.focus();
    wasActive.current = status !== "idle";
    if (status !== "recording") return;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [status]);
  useEffect(() => { words.current?.scrollTo({ top: words.current.scrollHeight }); }, [voice.text]);

  const active = status !== "idle";
  const icon = compact ? "size-8" : "size-9";
  const action = "inline-flex h-9 items-center gap-1.5 rounded-xl px-3 text-sm font-medium disabled:opacity-40";
  const label = status === "starting" ? "Starting the microphone…" : status === "finishing" ? "Finishing…" : "Listening…";
  return <>
    <button ref={mic} type="button" onClick={() => void start()} onContextMenu={event => event.preventDefault()} disabled={disabled || active}
      aria-label="Talk: record a voice message" title="Talk" className={`flex shrink-0 touch-manipulation items-center justify-center rounded-lg text-muted-foreground select-none hover:bg-muted hover:text-foreground disabled:opacity-40 ${icon}`}>
      <Mic className="size-4" aria-hidden="true" /></button>
    {voice.error && !active && <p role="alert" className="absolute bottom-full left-0 mb-2 flex max-w-full items-center gap-2 rounded-lg border border-border bg-card px-3 py-1.5 text-xs text-danger shadow-sm">
      {voice.error}<button type="button" onClick={voice.cancel} aria-label="Dismiss" className="rounded p-0.5 text-muted-foreground hover:text-foreground"><X className="size-3" aria-hidden="true" /></button></p>}
    {active && <div role="group" aria-label="Voice message" onKeyDown={event => { if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); voice.cancel(); } }}
      className="absolute inset-0 z-10 flex min-h-28 flex-col gap-2 rounded-[inherit] border border-muted-foreground/60 bg-card p-2.5">
      <p ref={words} aria-live="polite" className={`min-h-0 flex-1 overflow-y-auto px-1 whitespace-pre-wrap ${compact ? "text-sm" : "text-[15px]"} ${voice.text ? "" : "text-muted-foreground"}`}>{voice.text || label}</p>
      <div className="flex items-center gap-2">
        <span className="flex h-5 items-center gap-0.5" aria-hidden="true">{[0.5, 0.8, 1, 0.8, 0.5].map((scale, index) =>
          <span key={index} className="w-1 rounded-full bg-danger transition-[height] duration-100" style={{ height: `${4 + Math.round(voice.level * scale * 16)}px` }} />)}</span>
        <span className="font-mono text-xs text-muted-foreground"><span className="sr-only">Recording </span>{clock(status === "recording" ? Math.max(0, now - voice.startedAt) : 0)} / {clock(VOICE_MAX_SECONDS * 1000)}</span>
        <span className="ml-auto" />
        <button type="button" onClick={() => { voice.cancel(); mic.current?.focus(); }} aria-label="Cancel and discard recording" className={`${action} text-muted-foreground hover:bg-muted hover:text-foreground`}><X className="size-4" aria-hidden="true" /><span className="max-sm:sr-only">Cancel</span></button>
        <button ref={done} type="button" onClick={() => void voice.done()} disabled={status !== "recording"} aria-label="Done: put the words in the box to edit" className={`${action} border border-input hover:bg-muted`}><Check className="size-4" aria-hidden="true" />Done</button>
        <button type="button" onClick={() => void voice.send()} disabled={status !== "recording"} aria-label="Send now" className={`${action} bg-primary text-primary-foreground hover:opacity-90`}><ArrowUp className="size-4" aria-hidden="true" />Send</button>
      </div>
    </div>}
  </>;
}
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { STANDALONE_KINDS } from "./open-proposals";
import { callTaskSchema, callTurnSchema, type CallTurn } from "./voice-call-record";

export type CallExchange = { id: string; role: string; content: string; created_at: string };
/** A finished call as the chat shows it: the summary, its cards, the transcript and the chat messages it produced. */
export type CallCard = {
  id: string; durationSeconds: number; summary: string | null; summaryStatus: "pending" | "done" | "failed";
  transcript: CallTurn[];
  /** Requests still running when the call ended, with where they stand now. */
  unfinished: { text: string; status: "running" | "completed" | "failed" | "canceled" }[];
  /** Card ids made during the call, oldest first; each card loads its own current state. */
  cards: string[];
  exchanges: CallExchange[];
};
type CallRow = { id: string; duration_seconds: number; transcript: unknown; tasks: unknown; request_ids: string[]; summary: string | null; summary_status: CallCard["summaryStatus"]; created_at: string };

/** Calls to show on a page of messages (saved within its time range) and the request ids whose messages they replace. */
export async function loadCalls(supabase: SupabaseClient, workspace: string, conversation: string, page: { requestIds: string[]; from?: string; to?: string }) {
  let shown = supabase.from("voice_calls").select("id,duration_seconds,transcript,tasks,request_ids,summary,summary_status,created_at")
    .eq("workspace_id", workspace).eq("conversation_id", conversation).order("created_at", { ascending: false }).limit(20);
  if (page.from) shown = shown.gte("created_at", page.from);
  if (page.to) shown = shown.lt("created_at", page.to);
  // A call whose card is on a newer page can still own messages on this one.
  const owners = page.requestIds.length
    ? supabase.from("voice_calls").select("request_ids").eq("workspace_id", workspace).eq("conversation_id", conversation).overlaps("request_ids", page.requestIds)
    : null;
  const [calls, owning] = await Promise.all([shown, owners]);
  if (calls.error || owning?.error) throw new Error("Could not load calls. Try again.");
  const rows = (calls.data ?? []) as CallRow[];
  const hidden = new Set([...rows, ...(owning?.data ?? []) as Pick<CallRow, "request_ids">[]].flatMap(row => row.request_ids));
  if (!rows.length) return { hidden, items: [] };

  const requestIds = [...new Set(rows.flatMap(row => row.request_ids))];
  const running = [...new Set(rows.flatMap(row => parseTasks(row.tasks).filter(task => task.status === "running").map(task => task.requestId)))];
  const [messages, cards, requests] = await Promise.all([
    requestIds.length ? supabase.from("messages").select("id,role,content,created_at,request_id,reply_to").eq("workspace_id", workspace).eq("conversation_id", conversation)
      .or(`request_id.in.(${requestIds.join(",")}),reply_to.in.(${requestIds.join(",")})`).order("created_at") : null,
    requestIds.length ? supabase.from("agent_proposals").select("id,chat_request_id").eq("workspace_id", workspace).in("chat_request_id", requestIds).in("kind", STANDALONE_KINDS).order("created_at") : null,
    running.length ? supabase.from("chat_requests").select("id,status").eq("workspace_id", workspace).in("id", running) : null,
  ]);
  if (messages?.error || cards?.error || requests?.error) throw new Error("Could not load calls. Try again.");
  const status = new Map((requests?.data ?? []).map(row => [row.id as string, row.status as CallCard["unfinished"][number]["status"]]));

  const items = rows.map(row => {
    const own = new Set(row.request_ids);
    const tasks = parseTasks(row.tasks);
    const transcript = z.array(callTurnSchema).safeParse(row.transcript);
    return {
      id: row.id, role: "assistant", content: "", created_at: row.created_at,
      call: {
        id: row.id, durationSeconds: row.duration_seconds, summary: row.summary, summaryStatus: row.summary_status,
        transcript: transcript.success ? transcript.data : [],
        unfinished: tasks.filter(task => task.status === "running").map(task => ({ text: task.text, status: status.get(task.requestId) ?? "running" })),
        cards: (cards?.data ?? []).filter(card => own.has(card.chat_request_id as string)).map(card => card.id as string),
        exchanges: (messages?.data ?? []).filter(message => own.has((message.request_id ?? message.reply_to) as string))
          .map(({ id, role, content, created_at }) => ({ id, role, content, created_at } as CallExchange)),
      } satisfies CallCard,
    };
  });
  return { hidden, items };
}

const parseTasks = (tasks: unknown) => z.array(callTaskSchema).catch([]).parse(tasks);
import { useEffect, useState } from "react";
import { startVoiceRecording, type VoiceHandlers, type VoiceRecording } from "./voice-recorder";

export const VOICE_MAX_SECONDS = 120;

export type VoiceStatus = "idle" | "starting" | "recording" | "finishing";
export type VoiceAction = "send" | "done";
export type VoiceState = { status: VoiceStatus; text: string; level: number; error: string; startedAt: number };
export const IDLE_VOICE: VoiceState = { status: "idle", text: "", level: 0, error: "", startedAt: 0 };

/**
 * One mic, the same for a tap or a hold: start records with live words; Send and Done both stop and hand the
 * transcript over (`send` straight away, `done` into the input to edit); cancel throws it away.
 * Hitting the length limit acts as Done, so nothing said is lost.
 */
export function createVoiceInput({ record, onFinish, onChange, maxSeconds = VOICE_MAX_SECONDS, now = Date.now }: {
  record: (handlers: VoiceHandlers) => Promise<VoiceRecording>; onFinish: (action: VoiceAction, text: string) => void;
  onChange: (state: VoiceState) => void; maxSeconds?: number; now?: () => number;
}) {
  let state = IDLE_VOICE, recording: VoiceRecording | null = null, run = 0, limit: ReturnType<typeof setTimeout> | undefined, finished = onFinish;
  const set = (patch: Partial<VoiceState>) => { state = { ...state, ...patch }; onChange(state); };
  // Each start, stop or cancel begins a new run, so late events from an older one are ignored.
  const reset = (patch: Partial<VoiceState> = {}) => { run++; clearTimeout(limit); recording = null; set({ ...IDLE_VOICE, ...patch }); };

  async function start() {
    if (state.status !== "idle") return;
    const current = ++run;
    set({ ...IDLE_VOICE, status: "starting" });
    const live = <T>(handler: (value: T) => void) => (value: T) => { if (current === run) handler(value); };
    try {
      const next = await record({ onText: live<string>(text => set({ text })), onLevel: live<number>(level => set({ level })), onError: live(fail) });
      if (current !== run) return next.cancel();
      recording = next;
      set({ status: "recording", startedAt: now() });
      limit = setTimeout(() => void finish("done"), maxSeconds * 1000);
    } catch (error) { if (current === run) fail(error); }
  }

  async function finish(action: VoiceAction) {
    if (state.status !== "recording" || !recording) return;
    const current = run, active = recording;
    clearTimeout(limit);
    set({ status: "finishing", level: 0 });
    const heard = (await active.stop().catch(() => state.text)).trim() || state.text.trim();
    if (current !== run) return;
    reset(heard ? {} : { error: "Didn't catch that. Try again." });
    if (heard) finished(action, heard);
  }

  function cancel() {
    recording?.cancel();
    if (state.status !== "idle" || state.error) reset();
  }

  // A dropped connection keeps what was already heard in the input instead of losing it.
  function fail(error: unknown) {
    const heard = state.text.trim();
    recording?.cancel();
    reset({ error: error instanceof Error ? error.message : "Voice input failed. Try again." });
    if (heard) finished("done", heard);
  }

  return { start, send: () => finish("send"), done: () => finish("done"), cancel, get state() { return state; },
    /** Swaps in the latest handler, so a re-rendered composer sees its current text. */
    setOnFinish: (handler: typeof onFinish) => { finished = handler; } };
}

/** React binding for the shared voice input; recording stops if the composer unmounts. */
export function useVoiceInput(onFinish: (action: VoiceAction, text: string) => void, record = startVoiceRecording) {
  const [state, setState] = useState(IDLE_VOICE);
  const [voice] = useState(() => createVoiceInput({ record, onFinish, onChange: setState }));
  useEffect(() => voice.setOnFinish(onFinish));
  useEffect(() => () => voice.cancel(), [voice]);
  return { ...state, start: voice.start, send: voice.send, done: voice.done, cancel: voice.cancel };
}
-- One row per artifact build. A build keeps running after the user leaves the page, so this is
-- how they find it again: running, then completed with the saved version, or failed with why.
create table public.artifact_builds (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  -- The artifact being changed; for a new artifact, set once it is saved.
  artifact_id uuid references public.artifacts(id) on delete cascade,
  prompt text not null check (length(btrim(prompt)) between 1 and 4000),
  status text not null default 'running' check (status in ('running','completed','failed')),
  version integer check (version >= 1),
  error text check (length(error) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index artifact_builds_workspace_created on public.artifact_builds(workspace_id, created_at desc);

alter table public.artifact_builds enable row level security;
create policy own_artifact_builds on public.artifact_builds for all to authenticated
using (public.owns_workspace(workspace_id))
with check (public.owns_workspace(workspace_id) and (artifact_id is null or exists (
  select 1 from public.artifacts where id = artifact_id and workspace_id = artifact_builds.workspace_id
)));
grant select, insert on public.artifact_builds to authenticated;
grant update (artifact_id, status, version, error, updated_at) on public.artifact_builds to authenticated;
-- One record per finished voice call in a conversation: how long it lasted, the live-caption transcript, the
-- requests it started (their chat messages are grouped under the call in the chat) and a short summary that is
-- written after hang-up.
create table public.voice_calls (
  id uuid primary key,
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  duration_seconds integer not null check (duration_seconds between 0 and 86400),
  transcript jsonb not null check (jsonb_typeof(transcript) = 'array' and octet_length(transcript::text) <= 60000),
  tasks jsonb not null check (jsonb_typeof(tasks) = 'array' and octet_length(tasks::text) <= 60000),
  summary text check (length(summary) <= 2000),
  summary_status text not null default 'pending' check (summary_status in ('pending','done','failed')),
  created_at timestamptz not null default now()
);
create index voice_calls_conversation_created on public.voice_calls(conversation_id, created_at);

alter table public.voice_calls enable row level security;
create policy own_voice_calls on public.voice_calls for all to authenticated
using (public.owns_workspace(workspace_id))
with check (public.owns_workspace(workspace_id) and exists (
  select 1 from public.conversations where id = conversation_id and workspace_id = voice_calls.workspace_id
));
revoke all on public.voice_calls from public, anon;
grant select, insert on public.voice_calls to authenticated;
grant update (summary, summary_status) on public.voice_calls to authenticated;
-- The chat requests a call started, so the chat can find and group their messages under the call.
alter table public.voice_calls add column request_ids uuid[] not null default '{}' check (cardinality(request_ids) <= 30);
create index voice_calls_request_ids on public.voice_calls using gin (request_ids);
grant insert (request_ids) on public.voice_calls to authenticated;
